1	/*
2	 * MPU6050 -> Arduino Uno -> Relative Angles on the Serial Plotter
3	 * ---------------------------------------------------------------
4	 * LIBRARIES NEEDED:
5	 *   - Wire.h  (built into the Arduino IDE, no install needed)
6	 *   This sketch talks to the MPU6050 directly over I2C registers, so no
7	 *   external MPU6050 or Kalman library needs to be installed.
8	 *
9	 * WIRING:
10	 *   MPU6050 VCC -> Arduino 5V (or 3.3V, check your board)
11	 *   MPU6050 GND -> Arduino GND
12	 *   MPU6050 SCL -> Arduino A5 (Uno hardware I2C clock pin)
13	 *   MPU6050 SDA -> Arduino A4 (Uno hardware I2C data pin)
14	 *   (On an Uno, I2C pins are fixed to A4/A5, so they are not configurable.)
15	 *
16	 * USAGE:
17	 *   Upload this sketch, then open Tools > Serial Plotter (or Serial Monitor)
18	 *   and set the baud rate to match SERIAL_BAUD below.
19	 *   Output is Roll, Pitch and Yaw in degrees, from -180 to 180.
20	 *
21	 * CALIBRATION:
22	 *   Keep the sensor still for about 1 second after every reset. Its position
23	 *   at that moment becomes 0,0,0.
24	 *
25	 * ACCURACY LIMITS:
26	 *   - Roll and Pitch use a Kalman filter that combines the gyro with gravity
27	 *     measured by the accelerometer, so they stay stable over time.
28	 *   - Yaw is integrated from the gyro only and WILL slowly drift. Rotating
29	 *     around the vertical axis does not change the gravity reading, so yaw has
30	 *     no reference to correct it. Fixing this requires a magnetometer.
31	 *   - Roll and Pitch are unreliable when Pitch is close to +-90 degrees.
32	 *   - Rotation faster than 250 deg/s exceeds the gyro range and causes error.
33	 */
34	
35	#include <Arduino.h>
36	#include <Wire.h>
37	
38	// ---------------- USER CONFIGURATION ----------------
39	#define MPU6050_ADDR 0x68       // change to 0x69 if AD0 pin is pulled high
40	#define SERIAL_BAUD 115200      // must match Serial Plotter baud rate
41	#define CALIBRATION_SAMPLES 200 // readings averaged to find the starting position
42	#define YAW_RATE_THRESHOLD 0.5  // yaw rates below this are ignored, in deg/s
43	
44	// Kalman tuning:
45	//   Raise Q_ANGLE to trust the gyro less and respond faster, at the cost of noise.
46	//   Raise R_MEASURE to trust the accelerometer less, for a smoother output.
47	#define Q_ANGLE 0.001
48	#define Q_BIAS 0.003
49	#define R_MEASURE 0.03
50	// ------------------------------------------------------
51	
52	// MPU6050 register addresses
53	#define REG_PWR_MGMT_1   0x6B
54	#define REG_ACCEL_XOUT_H 0x3B
55	
56	// Sensitivity scale factors for default full-scale ranges:
57	//   Accel: +-2g  -> 16384 LSB/g
58	//   Gyro:  +-250 deg/s -> 131 LSB/(deg/s)
59	const float ACCEL_SCALE = 16384.0;
60	const float GYRO_SCALE  = 131.0;
61	
62	struct Kalman {
63	  float angle;   // estimated angle, in degrees
64	  float bias;    // estimated gyro bias, in deg/s
65	  float P[2][2]; // error covariance
66	};
67	
68	Kalman kalmanRoll, kalmanPitch;
69	
70	float rollStart, pitchStart;
71	float yaw = 0;
72	float gyroXOffset, gyroYOffset, gyroZOffset; // in deg/s
73	unsigned long lastMicros;
74	
75	float wrapAngle(float angle) {
76	  while (angle > 180.0) angle -= 360.0;
77	  while (angle < -180.0) angle += 360.0;
78	  return angle;
79	}
80	
81	// Zeroes out values whose magnitude is below threshold (noise rejection)
82	float applyDeadzone(float value, float threshold) {
83	  if (value > -threshold && value < threshold) {
84	    return 0.0;
85	  }
86	  return value;
87	}
88	
89	void kalmanInit(Kalman &k, float startAngle) {
90	  k.angle = startAngle;
91	  k.bias = 0;
92	  k.P[0][0] = 0;
93	  k.P[0][1] = 0;
94	  k.P[1][0] = 0;
95	  k.P[1][1] = 0;
96	}
97	
98	void kalmanUpdate(Kalman &k, float measuredAngle, float gyroRate, float dt) {
99	  // Predict: advance the angle using the gyro
100	  k.angle += dt * (gyroRate - k.bias);
101	  k.P[0][0] += dt * (dt * k.P[1][1] - k.P[0][1] - k.P[1][0] + Q_ANGLE);
102	  k.P[0][1] -= dt * k.P[1][1];
103	  k.P[1][0] -= dt * k.P[1][1];
104	  k.P[1][1] += Q_BIAS * dt;
105	
106	  // Update: correct the prediction using the accelerometer angle
107	  float S = k.P[0][0] + R_MEASURE;
108	  float K0 = k.P[0][0] / S;
109	  float K1 = k.P[1][0] / S;
110	  float error = wrapAngle(measuredAngle - k.angle);
111	
112	  k.angle = wrapAngle(k.angle + K0 * error);
113	  k.bias += K1 * error;
114	
115	  float P00 = k.P[0][0];
116	  float P01 = k.P[0][1];
117	  k.P[0][0] -= K0 * P00;
118	  k.P[0][1] -= K0 * P01;
119	  k.P[1][0] -= K1 * P00;
120	  k.P[1][1] -= K1 * P01;
121	}
122	
123	int16_t readInt16() {
124	  uint8_t high = Wire.read();
125	  uint8_t low = Wire.read();
126	  return (int16_t)((high << 8) | low);
127	}
128	
129	// Reads accel and gyro together so all six values come from the same instant
130	void readSensor(float &ax, float &ay, float &az,
131	                float &gx, float &gy, float &gz) {
132	  Wire.beginTransmission(MPU6050_ADDR);
133	  Wire.write(REG_ACCEL_XOUT_H);
134	  Wire.endTransmission(false);
135	  Wire.requestFrom(MPU6050_ADDR, 14, true);
136	
137	  ax = readInt16() / ACCEL_SCALE;
138	  ay = readInt16() / ACCEL_SCALE;
139	  az = readInt16() / ACCEL_SCALE;
140	  readInt16(); // skip the temperature reading between accel and gyro
141	  gx = readInt16() / GYRO_SCALE;
142	  gy = readInt16() / GYRO_SCALE;
143	  gz = readInt16() / GYRO_SCALE;
144	}
145	
146	float accelRoll(float ay, float az) {
147	  return atan2(ay, az) * RAD_TO_DEG;
148	}
149	
150	float accelPitch(float ax, float ay, float az) {
151	  return atan2(-ax, sqrt(ay * ay + az * az)) * RAD_TO_DEG;
152	}
153	
154	void calibrate() {
155	  float sumAx = 0, sumAy = 0, sumAz = 0;
156	  float sumGx = 0, sumGy = 0, sumGz = 0;
157	  float ax, ay, az, gx, gy, gz;
158	
159	  for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
160	    readSensor(ax, ay, az, gx, gy, gz);
161	    sumAx += ax;
162	    sumAy += ay;
163	    sumAz += az;
164	    sumGx += gx;
165	    sumGy += gy;
166	    sumGz += gz;
167	    delay(5);
168	  }
169	
170	  gyroXOffset = sumGx / CALIBRATION_SAMPLES;
171	  gyroYOffset = sumGy / CALIBRATION_SAMPLES;
172	  gyroZOffset = sumGz / CALIBRATION_SAMPLES;
173	
174	  // Accel keeps its gravity reading, since gravity is what gives the tilt angle
175	  rollStart = accelRoll(sumAy, sumAz);
176	  pitchStart = accelPitch(sumAx, sumAy, sumAz);
177	
178	  kalmanInit(kalmanRoll, rollStart);
179	  kalmanInit(kalmanPitch, pitchStart);
180	}
181	
182	void setup() {
183	  Serial.begin(SERIAL_BAUD);
184	  Wire.begin();
185	
186	  // Wake up the MPU6050 (it starts in sleep mode)
187	  Wire.beginTransmission(MPU6050_ADDR);
188	  Wire.write(REG_PWR_MGMT_1);
189	  Wire.write(0x00);
190	  Wire.endTransmission();
191	
192	  delay(100);
193	
194	  calibrate();
195	  lastMicros = micros();
196	}
197	
198	void loop() {
199	  float ax, ay, az, gx, gy, gz;
200	  readSensor(ax, ay, az, gx, gy, gz);
201	
202	  unsigned long now = micros();
203	  float dt = (now - lastMicros) / 1000000.0;
204	  lastMicros = now;
205	
206	  kalmanUpdate(kalmanRoll, accelRoll(ay, az), gx - gyroXOffset, dt);
207	  kalmanUpdate(kalmanPitch, accelPitch(ax, ay, az), gy - gyroYOffset, dt);
208	
209	  // Yaw has no accelerometer measurement, so the Kalman update has nothing to use
210	  yaw = wrapAngle(yaw + applyDeadzone(gz - gyroZOffset, YAW_RATE_THRESHOLD) * dt);
211	
212	  // Labeled, comma-separated output for the Serial Plotter
213	  Serial.print("Roll:");
214	  Serial.print(wrapAngle(kalmanRoll.angle - rollStart), 2);
215	  Serial.print(",Pitch:");
216	  Serial.print(wrapAngle(kalmanPitch.angle - pitchStart), 2);
217	  Serial.print(",Yaw:");
218	  Serial.println(yaw, 2);
219	
220	  delay(20); // ~50 Hz update rate
221	}
